namespace LocalLens {
 public sealed partial class AuditEngine {
  string SoftwareMarker(string installed,string enabled){
   var processes=new List<string>();int failed=0;foreach(var p in System.Diagnostics.Process.GetProcesses()){try{processes.Add(p.ProcessName);}catch{failed++;}finally{p.Dispose();}}
   var names=processes.Where(n=>ChinaEvidence.SoftwareFamilies(n).Length>0).Distinct().OrderBy(n=>n).Take(40).ToArray();
   return "DOMESTIC_SOFTWARE="+new JavaScriptSerializer().Serialize(new{installed=ChinaEvidence.SoftwareFamilies(installed),enabled=ChinaEvidence.SoftwareFamilies(enabled),running=ChinaEvidence.SoftwareFamilies(String.Join("\n",names)),runningProcessNames=names,processReadFailures=failed});
  }
  void ExtendedScan(){
   Run(25,BrowserLanguage);Run(66,Extensions);
   if(options.BrowserContent){Run(34,BrowserHistory);Run(35,BrowserStorage);Run(52,BrowserAutofill);}else foreach(int id in new[]{34,35,52})Skip(id,"高级选项未启用浏览器内容分析");
   Run(33,()=>{string s=PS("Get-DnsClientCache | Select-Object -First 200 Entry,RecordName,RecordType,Data | ConvertTo-Json -Depth 3 -Compress",18000);string policy=PS("Get-DnsClientNrptPolicy | Select-Object -First 50 Namespace,NameServers | ConvertTo-Json -Depth 3 -Compress");Info(33,"DNS 缓存（最多 200 条）：\r\n"+s+"\r\nNRPT：\r\n"+policy+"\r\nDNS 缓存仅说明历史解析，不证明访问或物理位置；不代表浏览器 DoH 或实际递归 DNS 出口。","已读取 DNS 缓存和名称解析策略");});
   if(options.RequestLocation)Run(12,SystemLocation);else Skip(12,"未启用系统定位请求（需要系统许可）");
   if(options.Wifi){Run(16,()=>Info(16,PS("Get-CimInstance Win32_PnPEntity | Where-Object {$_.PNPClass -in @('Bluetooth','PrintQueue')} | Select-Object -First 100 Name,Manufacturer,Status | ConvertTo-Json -Compress")+"\r\n邻居缓存：\r\n"+PS("Get-NetNeighbor | Select-Object -First 100 InterfaceAlias,IPAddress,LinkLayerAddress,State | ConvertTo-Json -Compress"),"已查询配对 / 已发现设备及邻居缓存；没有主动扫描周边设备"));Run(15,()=>Info(15,Command(Path.Combine(Environment.SystemDirectory,"netsh.exe"),"mbn show interfaces")+"\r\n"+PS("Get-CimInstance Win32_POTSModem | Select-Object Name,Status | ConvertTo-Json -Compress"),"已读取移动宽带接口；注册网、SIM 地区字段依驱动支持而定"));}else Skip(16,"无线 / 邻居设备检查未启用");
   if(options.History){Run(36,RecentLinks);Run(37,()=>InstallationLogs(false));Run(38,()=>InstallationLogs(true));Run(39,Recycle);Run(40,DumpHeaders);Run(67,Activity);}else foreach(int id in new[]{36,37,38,39,40,67})Skip(id,"历史检查未启用");
   Run(42,StartupInventory);Run(47,()=>Info(47,PS("Get-CimInstance Win32_PnPSignedDriver | Select-Object -First 300 DeviceName,Manufacturer,DriverProviderName,DriverVersion,IsSigned | ConvertTo-Json -Compress",18000),"已列出最多 300 项驱动来源 / 签名字段；不能据此判断使用国家"));
   if(options.DeviceIdentifiers)Run(46,()=>{string raw=Wmi("SELECT UUID FROM Win32_ComputerSystemProduct",new[]{"UUID"})+Wmi("SELECT SerialNumber FROM Win32_BIOS",new[]{"SerialNumber"});if(String.IsNullOrWhiteSpace(raw))throw new IOException("未取得硬件标识");Info(46,"SHA-256(device UUID + BIOS serial) = "+LocalData.Hash(LocalData.Canonical(raw))+"\r\n不保存明文序列号；标识哈希仍可关联设备，基线对比只说明值的变化。没有访问厂商销售 / 保修历史数据库。","已生成本机标识哈希，可与历史基线比较");});else Skip(46,"未启用设备标识哈希；设备销售历史需要厂商记录");
   Run(54,()=>{var lines=new List<string>();using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\OneDrive\Accounts",false)){if(key!=null)foreach(var name in key.GetSubKeyNames())using(var child=key.OpenSubKey(name,false)){string path=Convert.ToString(child.GetValue("UserFolder"));if(path.Length>0)lines.Add("OneDrive 根目录："+path+"；存在="+Directory.Exists(path));}}foreach(var path in new[]{Path.Combine(Roaming,@"Apple Computer\MobileSync\Backup"),Path.Combine(User,@"Apple\MobileSync\Backup")}){if(Directory.Exists(path))lines.Add("手机备份目录："+path+"；子目录数（上限 100）="+Directory.EnumerateDirectories(path).Take(100).Count());}Info(54,String.Join("\r\n",lines),lines.Count==0?"所查同步 / 备份配置未取得结果":"已读取同步根目录配置 / 本地手机备份目录元数据");});
   if(options.AutoDiscoverFiles||!String.IsNullOrWhiteSpace(options.ContentFolder))RunContent();else foreach(int id in new[]{49,50,51,55})Skip(id,"已关闭自动查找文件，且未指定内容目录");
   Run(53,WeatherCaches);
   Run(62,()=>CaptureInventory(62,"obs|snagit|camtasia|sharex|screenrec|bandicam|teamviewer|anydesk|rustdesk|sunlogin|todesk"));
   Run(63,()=>CaptureInventory(63,"autohotkey|ditto|clipclip|clipboardfusion|keylogger|hook"));
   NetworkProbes();Run(10,Monitor);
   if(!String.IsNullOrWhiteSpace(options.BrowserReportPath))Run(58,ImportBrowser);else Skip(58,"点击浏览器检查，保存 JSON 后在高级选项中导入");
   if(!String.IsNullOrWhiteSpace(options.ExternalEvidencePath))foreach(int id in new[]{56,57,59,60,61}){int item=id;Run(item,()=>ImportExternal(item));}else if(options.AutoDiscoverFiles)AutomaticExternalRecords();else foreach(int id in new[]{56,57,59,60,61})Set(id,"需外部记录","需要本人取得的平台 / 服务商记录；本机不能自动得知","可按包内 examples/external-evidence.json 格式整理记录后在高级选项导入。程序不登录或请求这些平台。","外部依赖");
   Run(65,CompareBaseline);
   Set(69,"未发现","隐私保护行为本身不是地区线索","该项是对方可能采用的决策规则，不是本机客观状态。程序展示网络与浏览器实际观测值，不因为防跟踪、代理或权限拒绝而判定在中国。","已按本项排除规则判定");
  }
  void RecentLinks(){string s=PS("$shell=New-Object -ComObject WScript.Shell; try { Get-ChildItem -LiteralPath ([Environment]::GetFolderPath('Recent')) -Filter '*.lnk' | Select-Object -First 200 | ForEach-Object { $l=$shell.CreateShortcut($_.FullName); [pscustomobject]@{Name=$_.Name;Target=$l.TargetPath} } | ConvertTo-Json -Compress } finally {[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($shell)}");Mark(36,s,Rules.HasHan(s),"最近文件快捷方式名称 / 目标含中文","所读快捷方式未发现中文标记","最近目录最多 200 条；不遍历目标文件");}
  void InstallationLogs(bool old){int id=old?38:37;var lines=new List<string>();int read=0,hit=0,failed=0;string win=old?Path.Combine(SystemDrive,@"Windows.old\Windows"):Environment.GetFolderPath(Environment.SpecialFolder.Windows);foreach(var path in new[]{Path.Combine(win,@"Panther\setupact.log"),Path.Combine(win,@"Panther\UnattendGC\setupact.log"),Path.Combine(win,@"INF\setupapi.dev.log")}){if(!File.Exists(path))continue;try{using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){int first=f.ReadByte(),second=f.ReadByte();Encoding encoding=first==255&&second==254?Encoding.Unicode:first==254&&second==255?Encoding.BigEndianUnicode:Encoding.UTF8;long offset=Math.Max(0,f.Length-2097152);if(offset%2!=0)offset--;f.Position=offset;using(var reader=new StreamReader(f,encoding,true)){string text=reader.ReadToEnd();read++;var matches=text.Split('\n').Where(x=>Rules.MainlandLocale(x)||Regex.IsMatch(x,@"(?i)(UILanguage|SystemLocale|InputLocale|UserLocale|TimeZone|InstallLanguage)")).Take(80).ToArray();hit+=matches.Count(Rules.MainlandLocale);lines.Add(path+"（尾部最多 2 MiB）\r\n"+String.Join("\r\n",matches));}}}catch(Exception ex){failed++;lines.Add(ex.Message);}}if(old)lines.Add("系统镜像 / 卷影副本没有自动挂载或解密；Windows.old 不存在不能证明从未使用其他设置。");Outcome(id,lines,hit,read,failed,"安装日志样本含大陆语言 / 时区标记","标准安装日志内容采样");}
  void Recycle(){string s=PS("$s=New-Object -ComObject Shell.Application; try {$folder=$s.NameSpace(10); if($null -eq $folder){throw 'Recycle bin namespace unavailable'}; @($folder.Items()) | Select-Object -First 200 | ForEach-Object {[pscustomobject]@{Name=$_.Name;From=$_.ExtendedProperty('System.Recycle.DeletedFrom');Deleted=$_.ExtendedProperty('System.Recycle.DateDeleted')}} | ConvertTo-Json -Compress} finally {[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($s)}",18000);Info(39,s,"已读取最多 200 项回收站元数据；不恢复文件，不扫描磁盘未分配空间");}
  void DumpHeaders(){var lines=new List<string>();int read=0,hit=0,failed=0;var files=new List<string>();string system=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"MEMORY.DMP");if(File.Exists(system))files.Add(system);string root=Path.Combine(Local,"CrashDumps");if(Directory.Exists(root))files.AddRange(Directory.EnumerateFiles(root,"*.dmp").Take(10));foreach(var file in files){try{using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){var b=new byte[2097152];int n=stream.Read(b,0,b.Length);var matches=Regex.Matches(Encoding.ASCII.GetString(b,0,n)+"\n"+Encoding.Unicode.GetString(b,0,n-n%2),@"(?i)(zh[-_]CN|China Standard Time|Asia/Shanghai|zh[-_]Hans[-_]CN)").Cast<Match>().Select(m=>m.Value).Distinct().ToArray();read++;hit+=matches.Length;lines.Add(Path.GetFileName(file)+"：读取开头 "+n+" 字节；匹配="+String.Join(", ",matches));}}catch(Exception ex){failed++;lines.Add(Path.GetFileName(file)+"："+ex.Message);}}lines.Add("仅对现成转储文件做可见字符串采样；没有创建内存转储，不读取活跃进程、pagefile 或 hiberfil；不能证明其他内存残留不存在。");Outcome(40,lines,hit,read,failed,"已有转储片段包含语言 / 时区字符串","最多 11 个文件，每个前 2 MiB");}
  void StartupInventory(){string original=F(42).Evidence;string services=PS("Get-CimInstance Win32_Service | Where-Object {$_.StartMode -eq 'Auto'} | Select-Object -First 200 Name,DisplayName,State,StartMode | ConvertTo-Json -Compress",18000);string tasks=PS("Get-ScheduledTask | Where-Object {$_.State -ne 'Disabled'} | Select-Object -First 200 TaskPath,TaskName,State | ConvertTo-Json -Compress",18000);Info(42,original+"\r\n自动服务：\r\n"+services+"\r\n已启用计划任务：\r\n"+tasks+"\r\n"+SoftwareMarker("",original+"\n"+services+"\n"+tasks),"已读取启动项、自动服务及计划任务名称；不是恶意软件判定");}
  void CaptureInventory(int id,string pattern){string s=PS("Get-Process | Where-Object {$_.ProcessName -match '"+pattern+"'} | Select-Object ProcessName,Id | ConvertTo-Json -Compress");Mark(id,"匹配规则："+pattern+"\r\n候选进程：\r\n"+s,Regex.IsMatch(s,@"""ProcessName""\s*:"),"进程名称命中本项工具名单","运行进程名称未命中本项工具名单","已查询进程名称 / 工具能力线索");}
  void Activity(){string s=PS("$f=@{LogName='System';StartTime=(Get-Date).AddDays(-7);Id=1,12,13,42,6005,6006}; $events=Get-WinEvent -FilterHashtable $f -MaxEvents 300 -ErrorAction SilentlyContinue; if($null -eq $events){$l=Get-WinEvent -ListLog System; 'No matching events; total log entries='+$l.RecordCount} else {$events | Group-Object {$_.TimeCreated.ToString('HH')} | Sort-Object Name | Select-Object Name,Count | ConvertTo-Json -Compress}",18000);Info(67,s+"\r\n只统计系统启动、停止、唤醒等事件的本地小时；后台事件不等于有人操作，不能证明用户作息或地区。","已生成近 7 天最多 300 条系统事件的小时分布");}
  void WeatherCaches(){WeatherCachesAt(Path.Combine(Local,"Packages"));}
  void WeatherCachesAt(string root){var lines=new List<string>();int scanned=0,hit=0,failed=0;if(Directory.Exists(root))foreach(var package in Directory.EnumerateDirectories(root).Where(d=>Regex.IsMatch(Path.GetFileName(d),@"(?i)^(Microsoft\.BingWeather|Microsoft\.WindowsMaps)_"))){string dir=Path.Combine(package,"LocalState");if(!Directory.Exists(dir))continue;var walk=LocalData.Walk(dir,100,20,cancel);failed+=walk.Errors.Count;if(walk.Capped)failed++;foreach(var f in walk.Files.Where(f=>Regex.IsMatch(Path.GetExtension(f),@"(?i)^\.(json|xml|txt|ini)$"))){try{string text=LocalData.ReadBounded(f,262144);scanned++;var matches=ChinaEvidence.LocationAssociationMarkers(text);if(matches.Length>0){hit++;lines.Add(Path.GetFileName(f)+"\r\n"+String.Join("\r\n",matches));}}catch(Exception e){failed++;lines.Add(e.Message);}}}lines.Insert(0,"仅检查传统 Windows 天气 / 地图应用 LocalState 的有限文本缓存；二进制数据库、新版 Web 小组件和云端偏好不在覆盖范围。");Outcome(53,lines,hit,scanned,failed,"可读天气 / 地图缓存包含地名字符串","已知应用文本缓存");}
  void CompareBaseline(){string baselinePath=options.BaselinePath;if(String.IsNullOrWhiteSpace(baselinePath)&&options.AutoDiscoverFiles)baselinePath=AutomaticBaseline.DefaultPath;baselineExisted=!String.IsNullOrWhiteSpace(baselinePath)&&File.Exists(baselinePath);if(String.IsNullOrWhiteSpace(baselinePath)||!baselineExisted){Skip(65,options.AutoDiscoverFiles?"首次扫描没有历史基线；完整扫描后自动保存，下次直接比较":"未选择历史基线，无法检查配置变化");return;}var before=Baseline.Load(baselinePath);var now=Baseline.Create(rows);var lines=new List<string>{"历史基线："+before.CreatedUtc,"只比较文件内保存的证据哈希；基线未签名，请自行确认来源。"};int compared=0,changed=0;foreach(var p in before.Hashes){string v;if(!now.Hashes.TryGetValue(p.Key,out v)){lines.Add(p.Key+"：本次缺少可比结果");continue;}compared++;bool different=v!=p.Value;if(different)changed++;lines.Add(p.Key+" "+F(int.Parse(p.Key)).Title+"："+(different?"变化":"哈希一致"));}lines.Add("软件更新、权限或采样差异均可导致变化；未更改的有限配置不能排除网络或程序篡改。");Outcome(65,lines,changed,compared,0,"相对所选基线，部分配置 / 标识发生变化","选定配置哈希比较；不等同完整性证明");}
  void ImportExternal(int id){var d=LocalData.Json(options.ExternalEvidencePath,1048576);if(Value(d,"format")!="LocalLens External Evidence 1")throw new FormatException("外部记录格式不匹配");object raw;if(!d.TryGetValue("records",out raw)||!(raw is IEnumerable))throw new FormatException("records 数组缺失");var lines=new List<string>();int count=0,hit=0;foreach(var item in (IEnumerable)raw){var r=item as Dictionary<string,object>;if(r==null)throw new FormatException("record 必须为对象");int check;if(!int.TryParse(Value(r,"checkId"),out check)||!new[]{56,57,59,60,61}.Contains(check))throw new FormatException("外部记录 checkId 无效");if(check!=id)continue;if(++count>200)throw new FormatException("每类外部记录最多 200 条");string code=Value(r,"countryCode").ToUpperInvariant();if(code.Length>0&&!Regex.IsMatch(code,"^[A-Z]{2}$"))throw new FormatException("countryCode 必须为两位字母代码");if(String.IsNullOrWhiteSpace(Value(r,"source"))||String.IsNullOrWhiteSpace(Value(r,"observedAt")))throw new FormatException("缺少来源 / 观察时间");DateTimeOffset date;if(!DateTimeOffset.TryParse(Value(r,"observedAt"),out date))throw new FormatException("记录时间无效");if(code.Length==0){lines.Add("来源="+Value(r,"source")+"；此记录无国家字段，只能作补充说明。");}if(code=="CN")hit++;lines.Add("来源="+Value(r,"source")+" | 时间="+Value(r,"observedAt")+" | 国家="+code+" | 设备标签="+Value(r,"deviceTag")+" | 说明="+Value(r,"note"));}if(count==0){Set(id,"需外部记录","导入文件没有此项记录","没有对此项给出通过结论。","缺少记录");return;}lines.Insert(0,"只分析用户导入记录；没有验证平台来源真实性，没有访问平台后台。文件内容不会被执行或联网发送。");if(hit==0&&lines.Any(x=>x.Contains("此记录无国家字段"))){Set(id,"未检测","导入记录缺少国家字段，地区判定未完成",String.Join("\r\n",lines),"缺少 countryCode");return;}Outcome(id,lines,hit,count,0,"导入记录包含中国大陆国家标记","用户提供的外部证据");}
 }
